  )
  update public.state_rule_source_candidates candidate
  set candidate_status = 'CAPTURED_EXACT_BYTES_PENDING_INDEPENDENT_VALIDATION',
      agent_verification_status = case
        when candidate.agent_verification_status in ('verified', 'rejected')
          then candidate.agent_verification_status
        else 'captured_unvalidated'
      end,
      exact_bytes_captured = true,
      source_sha256 = captures.sha256,
      retrieved_at = captures.retrieved_at,
      verification_evidence = coalesce(candidate.verification_evidence, '{}'::jsonb)
        || jsonb_build_object(
          'capture_actor', 'github_actions',
          'capture_workflow', 'Remaining State Source Evidence',
          'capture_run_id', 33239426284,
          'capture_artifact_id', 9710896795,
          'capture_artifact_sha256', '45f4f001284d282a82d0d88a9bf1ba03a73ad2be6ba43b8d95615cc2b7456988',
          'capture_manifest', 'artifacts/remaining-state-source-evidence.json',
          'final_url', captures.final_url,
          'content_type', captures.content_type,
          'capture_kind', captures.capture_kind,
          'captured_byte_size', captures.byte_size,
          'independent_validation_required', true,
          'human_verified', false
        ),
      compliance_activation_allowed = false,
      updated_at = now()
  from captures
  where candidate.state_code = captures.state_code
    and candidate.source_type = captures.source_type
    and candidate.source_url = captures.source_url;

  get diagnostics captured_updates = row_count;
  if captured_updates <> 113 then
    raise exception 'Remaining-source capture reconciliation expected 113 rows, updated %', captured_updates;
  end if;

  with blockers(state_code, source_type, source_url, attempted_at, blocker) as (
    values
      ('AZ','CONTROLLED_RESOURCE_INDEX','https://housing.az.gov/resources','2026-08-29T06:50:21.960Z'::timestamptz,'http_status:403'),
      ('AZ','RENTAL_COMPLIANCE_MANUAL_FORMS_LIMITS','https://housing.az.gov/programs/rental-compliance','2026-08-29T06:50:21.968Z'::timestamptz,'http_status:403'),
      ('FL','COMPLIANCE_GUIDEBOOK','https://www.floridahousing.org/owners-and-managers/compliance/compliance-guidebook','2026-08-29T06:50:25.224Z'::timestamptz,'fetch failed'),
      ('FL','COMPLIANCE_LIMITS_FORMS_UPDATES','https://www.floridahousing.org/owners-and-managers/compliance','2026-08-29T06:50:25.216Z'::timestamptz,'fetch failed'),
      ('FL','LIHTC_PROGRAM','https://www.floridahousing.org/programs/developers-multifamily-programs/low-income-housing-tax-credits','2026-08-29T06:50:25.510Z'::timestamptz,'fetch failed'),
      ('FL','NONCOMPETITIVE_QAP_DOCUMENTS','https://www.floridahousing.org/programs/developers-multifamily-programs/non-competitive/related-references-and-links','2026-08-29T06:50:26.053Z'::timestamptz,'fetch failed')
  )
  update public.state_rule_source_candidates candidate
  set agent_verification_status = case
        when candidate.agent_verification_status in ('verified', 'rejected')
          then candidate.agent_verification_status
        else 'blocked'
      end,
      verification_evidence = coalesce(candidate.verification_evidence, '{}'::jsonb)
        || jsonb_build_object(
          'capture_actor', 'github_actions',
          'capture_workflow', 'Remaining State Source Evidence',
          'capture_run_id', 33239426284,
          'capture_artifact_id', 9710896795,
          'capture_artifact_sha256', '45f4f001284d282a82d0d88a9bf1ba03a73ad2be6ba43b8d95615cc2b7456988',
          'capture_manifest', 'artifacts/remaining-state-source-evidence.json',
          'last_capture_attempt_at', blockers.attempted_at,
          'capture_blocker', blockers.blocker,
          'independent_validation_required', true,
          'human_verified', false
        ),
      compliance_activation_allowed = false,
      updated_at = now()
  from blockers
  where candidate.state_code = blockers.state_code
    and candidate.source_type = blockers.source_type
    and candidate.source_url = blockers.source_url;

  get diagnostics blocked_updates = row_count;
  if blocked_updates <> 6 then
    raise exception 'Remaining-source blocker reconciliation expected 6 rows, updated %', blocked_updates;
  end if;

  select count(*) into remaining_missing
  from public.state_rule_source_candidates
  where not (
    exact_bytes_captured
    and coalesce(source_sha256, '') ~ '^[0-9a-f]{64}$'
  );

  if remaining_missing <> 6 then
    raise exception 'Expected 6 inaccessible authority indexes after capture, found %', remaining_missing;
  end if;

  update public.state_rule_pack_candidates pack
  set status = 'agent_verification_in_progress',
      source_candidate_count = (
        select count(*) from public.state_rule_source_candidates source
        where source.state_code = pack.state_code
      ),
      blocked_source_count = (
        select count(*) from public.state_rule_source_candidates source
        where source.state_code = pack.state_code
          and source.agent_verification_status = 'blocked'
      ),
      candidate_manifest = pack.candidate_manifest || jsonb_build_object(
        'remaining_source_capture_manifest', 'artifacts/remaining-state-source-evidence.json',
        'remaining_source_capture_count', 113,
        'remaining_source_blocked_count', 6,
        'remaining_source_capture_run_id', 33239426284,
        'independent_validation_required', true
      ),
      compliance_activation_allowed = false,
      updated_at = now()
  where exists (
    select 1 from public.state_rule_source_candidates source
    where source.state_code = pack.state_code
  );
end
